import Complaint from '../models/Complaint.js';
import Maintenance from '../models/Maintenance.js';
import Elevator from '../models/Elevator.js';
import { CATEGORY_LABELS } from '../config/constants.js';
import { daysBetween } from '../utils/helpers.js';

const DAY = 86400000;
const round = (n, d = 0) => (n == null ? null : Number(n.toFixed(d)));

/**
 * Rule-based analysis of real complaint and maintenance records.
 * Nothing here is generated by AI and no sensor data is used or invented.
 */
export async function computeRuleBasedInsights({ windowDays = 180 } = {}) {
  const now = new Date();
  const since = new Date(now.getTime() - windowDays * DAY);

  const [complaints, maintenance, elevators] = await Promise.all([
    Complaint.find({ createdAt: { $gte: since }, status: { $ne: 'rejected' } }).populate('elevator', 'elevatorId building location').lean(),
    Maintenance.find({ status: { $ne: 'cancelled' } }).lean(),
    Elevator.find().lean(),
  ]);

  const completedServices = maintenance.filter((m) => m.status === 'completed' && m.completedAt);
  const lastServiceByKey = new Map();
  const lastServiceByElevator = new Map();
  completedServices.forEach((m) => {
    const eid = String(m.elevator);
    const prev = lastServiceByElevator.get(eid);
    if (!prev || m.completedAt > prev) lastServiceByElevator.set(eid, m.completedAt);
    (m.servicedComponents || []).forEach((sc) => {
      const key = `${eid}|${sc.component}`;
      const p = lastServiceByKey.get(key);
      if (!p || m.completedAt > p) lastServiceByKey.set(key, m.completedAt);
    });
  });

  const groups = new Map();
  complaints.forEach((c) => {
    if (!c.elevator) return;
    const component = c.component || c.category;
    const key = `${c.elevator._id}|${component}`;
    if (!groups.has(key)) groups.set(key, { elevator: c.elevator, component, faults: [] });
    groups.get(key).faults.push(c);
  });

  const items = [...groups.entries()].map(([key, g]) => {
    const dates = g.faults.map((f) => new Date(f.createdAt)).sort((a, b) => a - b);
    const faultCount = dates.length;
    const highCount = g.faults.filter((f) => ['high', 'critical'].includes(f.severity)).length;
    const openCount = g.faults.filter((f) => ['pending', 'assigned', 'in_progress'].includes(f.status)).length;
    const lastFaultAt = dates[dates.length - 1];
    const daysSinceLastFault = daysBetween(now, lastFaultAt);
    const lastServiceAt = lastServiceByKey.get(key) || null;
    const daysSinceService = lastServiceAt ? daysBetween(now, lastServiceAt) : null;

    let avgIntervalDays = null;
    if (faultCount >= 2) {
      const gaps = dates.slice(1).map((d, i) => (d - dates[i]) / DAY);
      avgIntervalDays = gaps.reduce((a, b) => a + b, 0) / gaps.length;
    }

    let score = faultCount * 12 + highCount * 10 + openCount * 10;
    if (daysSinceLastFault <= 30) score += 15;
    if (daysSinceService === null || daysSinceService > 120) score += 10;
    score = Math.min(100, score);

    const reasons = [`${faultCount} fault report${faultCount > 1 ? 's' : ''} in the last ${windowDays} days`];
    if (highCount) reasons.push(`${highCount} rated high or critical severity`);
    if (openCount) reasons.push(`${openCount} still unresolved`);
    if (daysSinceLastFault <= 30) reasons.push(`most recent fault ${daysSinceLastFault} day(s) ago`);
    if (daysSinceService === null) reasons.push('no recorded service for this component');
    else if (daysSinceService > 120) reasons.push(`last serviced ${daysSinceService} days ago`);

    const nextExpectedFault =
      faultCount >= 3 && avgIntervalDays ? new Date(lastFaultAt.getTime() + avgIntervalDays * DAY).toISOString() : null;

    return {
      elevatorId: g.elevator.elevatorId,
      elevatorRef: String(g.elevator._id),
      building: g.elevator.building,
      location: g.elevator.location,
      component: g.component,
      componentLabel: CATEGORY_LABELS[g.component] || g.component,
      faultCount,
      highSeverityCount: highCount,
      openCount,
      lastFaultAt,
      daysSinceLastFault,
      lastServiceAt,
      daysSinceService,
      avgIntervalDays: round(avgIntervalDays, 1),
      nextExpectedFault,
      score,
      priority: score >= 60 ? 'high' : score >= 35 ? 'medium' : 'low',
      reasons,
    };
  });
  items.sort((a, b) => b.score - a.score || b.faultCount - a.faultCount);

  const componentMap = new Map();
  items.forEach((i) => {
    const c = componentMap.get(i.component) || { component: i.component, label: i.componentLabel, totalFaults: 0, elevators: new Set(), highSeverity: 0 };
    c.totalFaults += i.faultCount;
    c.highSeverity += i.highSeverityCount;
    c.elevators.add(i.elevatorId);
    componentMap.set(i.component, c);
  });
  const components = [...componentMap.values()]
    .map((c) => ({ component: c.component, label: c.label, totalFaults: c.totalFaults, highSeverity: c.highSeverity, elevatorsAffected: c.elevators.size }))
    .sort((a, b) => b.totalFaults - a.totalFaults);

  const today = new Date(new Date().setHours(0, 0, 0, 0));
  const elevatorPriorities = elevators
    .map((e) => {
      const eid = String(e._id);
      const mine = items.filter((i) => i.elevatorRef === eid);
      const faults = mine.reduce((s, i) => s + i.faultCount, 0);
      const overdue = maintenance.filter((m) => String(m.elevator) === eid && ['scheduled', 'in_progress'].includes(m.status) && new Date(m.scheduledDate) < today).length;
      const last = lastServiceByElevator.get(eid) || null;
      const daysSince = last ? daysBetween(now, last) : null;
      let score = Math.min(60, faults * 6) + overdue * 15 + (daysSince === null || daysSince > 90 ? 15 : 0) + (e.status === 'out_of_service' ? 20 : 0);
      score = Math.min(100, score);
      return {
        elevatorId: e.elevatorId,
        building: e.building,
        location: e.location,
        status: e.status,
        faults,
        overdueMaintenance: overdue,
        lastServiceAt: last,
        daysSinceService: daysSince,
        score,
        priority: score >= 60 ? 'high' : score >= 35 ? 'medium' : 'low',
      };
    })
    .sort((a, b) => b.score - a.score);

  return {
    method: 'rule-based',
    disclaimer:
      'Rule-based estimate computed from recorded complaints and maintenance records only. It is not an AI prediction and uses no sensor data.',
    generatedAt: now,
    windowDays,
    dataSummary: { complaintsAnalyzed: complaints.length, maintenanceRecordsAnalyzed: maintenance.length, elevators: elevators.length },
    insufficientData: complaints.length < 5,
    components,
    items,
    elevatorPriorities,
  };
}

export const compactForAi = (insights) => ({
  windowDays: insights.windowDays,
  dataSummary: insights.dataSummary,
  components: insights.components.slice(0, 10).map((c) => ({ component: c.component, totalFaults: c.totalFaults, highSeverity: c.highSeverity, elevatorsAffected: c.elevatorsAffected })),
  items: insights.items.slice(0, 15).map((i) => ({
    elevatorId: i.elevatorId,
    component: i.component,
    faultCount: i.faultCount,
    highSeverityCount: i.highSeverityCount,
    openCount: i.openCount,
    daysSinceLastFault: i.daysSinceLastFault,
    daysSinceService: i.daysSinceService,
    avgIntervalDays: i.avgIntervalDays,
    ruleScore: i.score,
  })),
});
